/bin/bash -lc "cd [workspace path] && python3 << 'EOF'
import numpy as np
from scipy import ndimage
rgb = np.load('source_pixels.npz')['rgb']

def detect(frame, kind):
    f = rgb[frame].astype(int)
    r,g,b = f[...,0],f[...,1],f[...,2]
    if kind=='red':
        m = (r>170)&(g<170)&(b<170)&((r-g)>50)&((r-b)>50)
    elif kind=='blue':
        m = (b>170)&(r<170)&(g<180)&((b-r)>50)
    else:
        m = (r>235)&(g>235)&(b>235)
    lab,n = ndimage.label(m)
    best=None
    for i in range(1,n+1):
        ys,xs=np.where(lab==i)
        sz=len(ys)
        cx,cy=xs.mean(),ys.mean()
        # playfield region filter
        if 55<cx<235 and 40<cy<115 and 8<=sz<=400:
            if best is None or sz>best[0]:
                best=(sz,cx,cy,xs.min(),xs.max(),ys.min(),ys.max())
    return best

for kind in ['red','blue','white']:
    print(kind)
    for fr in range(0,96,6):
        print(fr, detect(fr,kind))
EOF"
